// Long-term memory: this customer's newest order, from the Orders sheet.
const chatId = String($('When Executed by Another Workflow').first().json.chat_id ?? '');
const rows = $input.all().map(i => i.json)
  .filter(r => r.order_id && String(r.chat_id) === chatId)
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
if (!chatId || !rows.length) return [{ json: { found: false } }];
const o = rows[0];
let items;
try { items = JSON.parse(o.items_json).map(l => ({ product: l.name, qty: l.qty, unit: l.unit })); }
catch (e) { items = o.items_json; }
return [{ json: { found: true, order_id: o.order_id, items, date: o.delivery_date || o.created_at } }];
